<?php
declare(strict_types=1);
use Illuminate\Support\Facades\Route;use Plugins\Modules\Phonetics\Http\Controllers\PhoneticsAdminController;use Plugins\Modules\Phonetics\Http\Controllers\PhoneticsPracticeController;
use Plugins\Modules\Phonetics\Http\Controllers\PhoneticsLearningAdminController;
use Plugins\Modules\Phonetics\Http\Controllers\PhoneticsLearningController;
use Plugins\Modules\Phonetics\Http\Controllers\PhoneticsExamController;
Route::middleware(config('phonetics.middleware.practice', ['web','installed','plugin:phonetics']))->prefix('courses/{courseSlug}/phonetics-practice')->name('plugins.phonetics.practice.')->group(function():void{Route::get('/',[PhoneticsPracticeController::class,'index'])->name('index');Route::post('/attempts',[PhoneticsPracticeController::class,'storeAttempt'])->middleware(array_merge(config('phonetics.middleware.attempt', ['web','auth']), ['throttle:30,1']))->name('attempts.store');});

Route::middleware(config('phonetics.middleware.practice', ['web','installed','plugin:phonetics']))->prefix('courses/{courseSlug}/phonetics-learning')->name('plugins.phonetics.learning.')->group(function():void{
 Route::get('/',[PhoneticsLearningController::class,'index'])->name('index');
 Route::post('/attempts',[PhoneticsLearningController::class,'attempt'])->middleware(array_merge(config('phonetics.middleware.attempt', ['web','auth']), ['throttle:30,1']))->name('attempt');
 Route::post('/recordings',[PhoneticsSpeakingRecordingController::class,'store'])->middleware(['auth','throttle:5,1'])->name('recordings.store');
 Route::get('/recordings',[PhoneticsSpeakingRecordingController::class,'history'])->middleware('auth')->name('recordings.history');
 Route::get('/recordings/{recording}/audio',[PhoneticsSpeakingRecordingController::class,'stream'])->middleware('auth')->name('recordings.audio');
 Route::delete('/recordings/{recording}',[PhoneticsSpeakingRecordingController::class,'destroy'])->middleware(['auth','throttle:10,1'])->name('recordings.destroy');
 Route::get('/exams/{examSlug}',[PhoneticsExamController::class,'start'])->middleware(array_merge(config('phonetics.middleware.exam', ['web','auth']), ['throttle:20,1']))->name('exams.start');
 Route::post('/exams/{examSlug}/attempts/{attempt}',[PhoneticsExamController::class,'submit'])->middleware(array_merge(config('phonetics.middleware.exam', ['web','auth']), ['throttle:10,1']))->name('exams.submit');
});
Route::middleware(config('phonetics.middleware.admin', ['web','installed','auth','plugin:phonetics','permission:phonetics.manage']))->prefix('admin/phonetics')->name('plugins.phonetics.admin.')->group(function():void{Route::get('/',[PhoneticsAdminController::class,'index'])->name('index');Route::get('/learning',[PhoneticsLearningAdminController::class,'index'])->name('learning');Route::get('/learning/recordings',[PhoneticsSpeakingRecordingController::class,'reviewQueue'])->name('learning.recordings');Route::get('/learning/recordings/{recording}/audio',[PhoneticsSpeakingRecordingController::class,'adminStream'])->name('learning.recordings.audio');Route::patch('/learning/recordings/{recording}/review',[PhoneticsSpeakingRecordingController::class,'review'])->name('learning.recordings.review');Route::get('/learning/lessons',[PhoneticsLearningAdminController::class,'lessons'])->name('learning.lessons');Route::post('/learning/assignments',[PhoneticsLearningAdminController::class,'storeAssignment'])->name('learning.assignments.store');Route::post('/learning/batch-members',[PhoneticsLearningAdminController::class,'storeBatchMember'])->name('learning.batch-members.store');Route::delete('/learning/batch-members/{membership}',[PhoneticsLearningAdminController::class,'destroyBatchMember'])->name('learning.batch-members.destroy');Route::delete('/learning/assignments/{assignment}',[PhoneticsLearningAdminController::class,'destroyAssignment'])->name('learning.assignments.destroy');Route::post('/learning/exams',[PhoneticsLearningAdminController::class,'storeExam'])->name('learning.exams.store');Route::patch('/learning/exams/{exam}/status',[PhoneticsLearningAdminController::class,'updateExamStatus'])->name('learning.exams.status');Route::patch('/settings',[PhoneticsAdminController::class,'updateSettings'])->name('settings');Route::post('/',[PhoneticsAdminController::class,'store'])->name('store');Route::put('/{entry}',[PhoneticsAdminController::class,'update'])->name('update');Route::delete('/{entry}',[PhoneticsAdminController::class,'destroy'])->name('destroy');});